namespace ghidra.framework;




using org.apache.commons.lang3;

using generic.jar;
using ghidra;
using ghidra.framework.preferences;
using ghidra.framework.remote;
using ghidra.net;
using ghidra.util;
using ghidra.util.classfinder;
using ghidra.util.exception;

public class HeadlessGhidraApplicationConfiguration : ApplicationConfiguration {

	/* @Override */
	protected void initializeApplication() {
		base.initializeApplication();
		
		try {
			// Install client-side deserialization filters (data/*.serial.filter)
			GhidraObjectInputFilter.configureClientSerialFilter();

			// Now that preferences are accessible, finalize classpath by adding user plugin paths.
			// This must be done before class searching.
			addUserJarAndPluginPathsToClasspath();

			monitor.setMessage("Performing class searching...");
			performClassSearching();

			// Locate certs if found (must be done before module initialization)
			locateCACertsFile();

			monitor.setMessage("Performing module initialization...");
			performModuleInitialization();
		}
		catch (Throwable t) {
			Msg.error(this, "Ghidra encountered a severe error during initialization", t);
			Environment.Exit(-1);
		}

		monitor.setMessage("Done initializing");
	}

	private void addUserJarAndPluginPathsToClasspath() {

		// In single jar mode, we probably didn't set the GhidraClassLoader on the command line,
		// so we can't support this.
		if (Application.inSingleJarMode()) {
			return;
		}

		// Make sure the Ghidra class loader is being used.  It might not be if we
		// get here from a test, for example.
		if (!(ClassLoader.getSystemClassLoader() is GhidraClassLoader)) {
			return;
		}

		GhidraClassLoader loader = (GhidraClassLoader) ClassLoader.getSystemClassLoader();
		foreach (string path in Preferences.getPluginPaths()) {
			loader.addPath(path);
		}
	}

	private void performClassSearching() {

		// The class searcher searches the classpath, and Ghidra's classpath should be complete
		// for this configuration at this point.
		try {
			ClassSearcher.search(monitor);
		}
		catch (CancelledException e) {
			Msg.debug(this, "Class searching unexpectedly cancelled.");
		}
	}

	/**
	 * Locate 'cacerts' file within the Ghidra root directory if 'ghidra.cacerts' property has not
	 * already been specified.  If found this will be used to establish the property which will be 
	 * used by {@link DefaultTrustManagerFactory}.
	 */
	private void locateCACertsFile() {
		
		string cacertsPath = System.getProperty(DefaultTrustManagerFactory.GHIDRA_CACERTS_PATH_PROPERTY);
		if (!StringUtils.isBlank(cacertsPath)) {
			return; // property will be used by DefaultTrustManagerFactory
		}
		
		foreach (ResourceFile appRoot in Application.getApplicationRootDirectories()) {
			File cacertsFile = new File(appRoot.getAbsolutePath(), "cacerts");
			if (cacertsFile.isFile()) {
				System.setProperty(DefaultTrustManagerFactory.GHIDRA_CACERTS_PATH_PROPERTY,
					cacertsFile.getAbsolutePath());
				break;
			}
		}
	}

	private void performModuleInitialization() {
		List<ModuleInitializer> instances = ClassSearcher.getInstances(typeof(ModuleInitializer));
		foreach (ModuleInitializer initializer in instances) {
			monitor.setMessage("Initializing " + initializer.getName() + "...");
			initializer.run();
		}
	}
}
